import itertools

def count_boundaries(s):
    return sum(1 for i in range(len(s)-1) if s[i] != s[i+1])

def simulate(s, k):
    s = list(s)
    visited = []
    while True:
        s_tuple = tuple(s)
        if s_tuple in visited:
            return False # Cycle without hitting target
        visited.append(s_tuple)

        if count_boundaries(s) <= 1:
            return True

        # Identify the k-th coin (1-indexed)
        coin_k = s[k-1]
        # Find the largest subsequence containing the k-th coin of the same metal
        left = k - 1
        while left > 0 and s[left-1] == coin_k:
            left -= 1
        right = k - 1
        while right < len(s) - 1 and s[right+1] == coin_k:
            right += 1

        # Subsequence is from index left to right (inclusive)
        block = s[left:right+1]
        remaining = s[:left] + s[right+1:]
        s = block + remaining

def check_k(n, k):
    # n is total coins, n/2 are A and n/2 are C
    # Generate all permutations of n/2 A's and n/2 C's
    coins = ['A'] * (n // 2) + ['C'] * (n // 2)
    for p in set(itertools.permutations(coins)):
        if not simulate(p, k):
            return False
    return True

for n in [4, 6, 8]:
    print(f"n={n}:", [k for k in range(1, n+1) if check_k(n, k)])

